from QuantConnect import *
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Orders import OrderStatus
from collections import deque
import math


class DailyStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.strategy_a_percent = float(
            self.GetParameter("StrategyAPercent")
        )

        self.close_history = {
            ticker: deque(maxlen=101)
            for ticker in self.symbols
        }
        self.previous_close = {}
        self.red_streak = 0

        self.rsi_period = 14
        self.rsi_previous_close = None
        self.rsi_gains = deque(maxlen=self.rsi_period)
        self.rsi_losses = deque(maxlen=self.rsi_period)
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.rsi_value = None

        self.lots = {
            "A": 0,
            "B": 0,
        }
        self.pending_orders = {
            "A": None,
            "B": None,
        }

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data):
        present = {}

        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                continue

            bar = data.Bars[symbol]
            present[ticker] = bar
            self.close_history[ticker].append(float(bar.Close))

        self._update_market_state(present)

        if self.IsWarmingUp:
            return

        if len(present) != len(self.symbols):
            return

        spy_history = self.close_history["SPY"]
        spy_cross_above = False
        spy_cross_below = False

        if len(spy_history) >= 101:
            previous_sma = sum(list(spy_history)[-101:-1]) / 100.0
            current_sma = sum(list(spy_history)[-100:]) / 100.0
            previous_spy_close = list(spy_history)[-2]
            current_spy_close = list(spy_history)[-1]

            spy_cross_above = (
                previous_spy_close <= previous_sma
                and current_spy_close > current_sma
            )
            spy_cross_below = (
                previous_spy_close >= previous_sma
                and current_spy_close < current_sma
            )

        aapl_red_buy = self.red_streak >= 3
        aapl_rsi_sell = self.rsi_value is not None and self.rsi_value > 60

        self._evaluate_sell_a(spy_cross_below)
        self._evaluate_sell_b(aapl_rsi_sell)

        self._evaluate_buy_a(spy_cross_above, present["SPY"].Close)
        self._evaluate_buy_b(aapl_red_buy, present["AAPL"].Close)

    def _update_market_state(self, present):
        if "AAPL" in present:
            close = float(present["AAPL"].Close)

            if self.previous_close.get("AAPL") is not None:
                if close < self.previous_close["AAPL"]:
                    self.red_streak += 1
                else:
                    self.red_streak = 0

            self.previous_close["AAPL"] = close
            self._update_rsi(close)

    def _update_rsi(self, close):
        if self.rsi_previous_close is None:
            self.rsi_previous_close = close
            return

        change = close - self.rsi_previous_close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)
        self.rsi_previous_close = close

        if self.rsi_average_gain is None:
            self.rsi_gains.append(gain)
            self.rsi_losses.append(loss)

            if len(self.rsi_gains) < self.rsi_period:
                return

            self.rsi_average_gain = sum(self.rsi_gains) / self.rsi_period
            self.rsi_average_loss = sum(self.rsi_losses) / self.rsi_period
        else:
            self.rsi_average_gain = (
                (self.rsi_average_gain * (self.rsi_period - 1)) + gain
            ) / self.rsi_period
            self.rsi_average_loss = (
                (self.rsi_average_loss * (self.rsi_period - 1)) + loss
            ) / self.rsi_period

        if self.rsi_average_loss == 0:
            self.rsi_value = 100.0
        else:
            relative_strength = (
                self.rsi_average_gain / self.rsi_average_loss
            )
            self.rsi_value = 100.0 - (
                100.0 / (1.0 + relative_strength)
            )

    def _evaluate_sell_a(self, reason):
        if (
            reason
            and self.lots["A"] > 0
            and self.pending_orders["A"] is None
        ):
            ticket = self.MarketOrder(
                self.symbols["SPY"],
                -self.lots["A"],
                tag="A_SELL"
            )
            self.pending_orders["A"] = ticket.OrderId

    def _evaluate_sell_b(self, reason):
        if (
            reason
            and self.lots["B"] > 0
            and self.pending_orders["B"] is None
        ):
            ticket = self.MarketOrder(
                self.symbols["AAPL"],
                -self.lots["B"],
                tag="B_SELL"
            )
            self.pending_orders["B"] = ticket.OrderId

    def _evaluate_buy_a(self, reason, close):
        if (
            reason
            and self.lots["A"] == 0
            and self.pending_orders["A"] is None
            and len(self.close_history["SPY"]) >= 101
        ):
            target_value = (
                self.Portfolio.TotalPortfolioValue
                * self.strategy_a_percent
                / 100.0
            )
            shares = int(math.floor(target_value / float(close)))

            if shares > 0:
                ticket = self.MarketOrder(
                    self.symbols["SPY"],
                    shares,
                    tag="A_BUY"
                )
                self.pending_orders["A"] = ticket.OrderId

    def _evaluate_buy_b(self, reason, close):
        if (
            reason
            and self.lots["B"] == 0
            and self.pending_orders["B"] is None
            and self.Portfolio.Cash >= 20000
        ):
            shares = int(math.floor(20000.0 / float(close)))

            if shares > 0:
                ticket = self.MarketOrder(
                    self.symbols["AAPL"],
                    shares,
                    tag="B_BUY"
                )
                self.pending_orders["B"] = ticket.OrderId

    def OnOrderEvent(self, order_event):
        if order_event.Status not in [
            OrderStatus.PartiallyFilled,
            OrderStatus.Filled
        ]:
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        tag = order.Tag
        quantity = int(order_event.FillQuantity)

        if tag == "A_BUY":
            self.lots["A"] += max(quantity, 0)
            if order_event.Status == OrderStatus.Filled:
                self.pending_orders["A"] = None

        elif tag == "A_SELL":
            self.lots["A"] = max(self.lots["A"] - abs(quantity), 0)
            if order_event.Status == OrderStatus.Filled:
                self.pending_orders["A"] = None

        elif tag == "B_BUY":
            self.lots["B"] += max(quantity, 0)
            if order_event.Status == OrderStatus.Filled:
                self.pending_orders["B"] = None

        elif tag == "B_SELL":
            self.lots["B"] = max(self.lots["B"] - abs(quantity), 0)
            if order_event.Status == OrderStatus.Filled:
                self.pending_orders["B"] = None
