            and self.spy_current_sma is not None
            and self._crosses_below(
                self.spy_previous_sma,
                self.spy_previous_sma,
                self.spy_current_sma,
                spy_close
            )
        )

        aapl_buy = self.aapl_red_streak >= 3
        aapl_sell = self.aapl_rsi is not None and self.aapl_rsi > 60

        if self.strategy_a_lot > 0 and spy_sell:
            self._sell_lot(self.spy, "Strategy A", True)

