                closes = list(self.spy_closes)
                self.spy_previous_sma = sum(closes[-100:]) / 100.0

            self.spy_closes.append(close)

            if len(self.spy_closes) >= 100:
                closes = list(self.spy_closes)
                self.spy_current_sma = sum(closes[-100:]) / 100.0

        if data.Bars.ContainsKey(self.aapl):
            close = float(data[self.aapl].Close)

            if self.aapl_previous_close is not None:
                if close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_previous_close = close
            self._update_rsi(close)

    def _update_rsi(self, close):
        if self.aapl_rsi_previous_close is None:
            self.aapl_rsi_previous_close = close
            return

        delta = close - self.aapl_rsi_previous_close
        gain = max(delta, 0.0)
        loss = max(-delta, 0.0)
        self.aapl_rsi_previous_close = close

        if self.aapl_average_gain is None:
            self.aapl_rsi_gains.append(gain)
            self.aapl_rsi_losses.append(loss)

            if len(self.aapl_rsi_gains) == self.aapl_rsi_period:
                self.aapl_average_gain = (
                    sum(self.aapl_rsi_gains) / self.aapl_rsi_period
                )
                self.aapl_average_loss = (
                    sum(self.aapl_rsi_losses) / self.aapl_rsi_period
                )
                self._calculate_rsi()
        else:
            period = self.aapl_rsi_period
            self.aapl_average_gain = (
                (self.aapl_average_gain * (period - 1)) + gain
            ) / period
            self.aapl_average_loss = (
                (self.aapl_average_loss * (period - 1)) + loss
            ) / period
            self._calculate_rsi()

    def _calculate_rsi(self):
        if self.aapl_average_loss == 0:
            self.aapl_rsi = 100.0
        else:
            relative_strength = (
                self.aapl_average_gain / self.aapl_average_loss
            )
            self.aapl_rsi = 100.0 - (100.0 / (1.0 + relative_strength))

    def _fully_formed(self):
        return (
            len(self.spy_closes) >= 100
            and self.spy_current_sma is not None
            and self.spy_previous_sma is not None
            and self.aapl_rsi is not None
        )

    def _crosses_above(self, previous_x, previous_y, current_x, current_y):
        return previous_x <= previous_y and current_x > current_y

    def _crosses_below(self, previous_x, previous_y, current_x, current_y):
        return previous_x >= previous_y and current_x < current_y

    def _sell_lot(self, symbol, tag, is_strategy_a):
        quantity = self.strategy_a_lot if is_strategy_a else self.strategy_b_lot

        if quantity <= 0:
            return

        ticket = self.MarketOrder(symbol, -quantity, False, tag + " sell")
        if ticket.Status == OrderStatus.Filled:
            if is_strategy_a:
                self.strategy_a_lot = 0
            else:
                self.strategy_b_lot = 0
